  8	    public IReadOnlyList<string> ParseRequestedColumns(string columnsArgument)
  9	    {
 10	        if (string.IsNullOrWhiteSpace(columnsArgument))
 11	        {
 12	            return Array.Empty<string>();
 13	        }
 14	
 15	        return columnsArgument
 16	            .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
 17	    }
