 19	    public async Task<string?> WriteSelectedColumnsAsync(
 20	        Stream input,
 21	        Stream output,
 22	        IReadOnlyList<string> requestedColumns)
 23	    {
 24	        if (requestedColumns.Count == 0)
 25	        {
 26	            return "No columns were selected.";
 27	        }
 28	
 29	        using var parser = new TextFieldParser(input, Encoding.UTF8)
 30	        {
 31	            TextFieldType = FieldType.Delimited,
 32	            HasFieldsEnclosedInQuotes = true,
 33	            TrimWhiteSpace = false
 34	        };
 35	
 36	        parser.SetDelimiters(",");
 37	
 38	        var headers = parser.ReadFields();
 39	        if (headers is null)
 40	        {
 41	            return "CSV file is empty.";
 42	        }
 43	
 44	        var selectedIndexes = new int[requestedColumns.Count];
 45	        for (var i = 0; i < requestedColumns.Count; i++)
 46	        {
 47	            var requestedColumn = requestedColumns[i];
 48	            var index = Array.FindIndex(headers, header => string.Equals(header, requestedColumn, StringComparison.OrdinalIgnoreCase));
 49	            if (index < 0)
 50	            {
 51	                return $"Column not found: {requestedColumn}";
 52	            }
 53	
 54	            selectedIndexes[i] = index;
 55	        }
 56	
 57	        await using var writer = new StreamWriter(output, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false), leaveOpen: true)
 58	        {
 59	            NewLine = "\r\n"
 60	        };
 61	
 62	        await writer.WriteLineAsync(BuildCsvRow(headers, selectedIndexes)).ConfigureAwait(false);
 63	
 64	        while (!parser.EndOfData)
 65	        {
 66	            var fields = parser.ReadFields();
 67	            if (fields is null)
 68	            {
 69	                continue;
 70	            }
 71	
 72	            await writer.WriteLineAsync(BuildCsvRow(fields, selectedIndexes)).ConfigureAwait(false);
 73	        }
 74	
 75	        await writer.FlushAsync().ConfigureAwait(false);
 76	        await output.FlushAsync().ConfigureAwait(false);
 77	        return null;
 78	    }
