 80	    private static string BuildCsvRow(IReadOnlyList<string> fields, IReadOnlyList<int> selectedIndexes)
 81	    {
 82	        var selectedFields = new string[selectedIndexes.Count];
 83	        for (var i = 0; i < selectedIndexes.Count; i++)
 84	        {
 85	            var selectedIndex = selectedIndexes[i];
 86	            selectedFields[i] = selectedIndex < fields.Count ? EscapeCsvField(fields[selectedIndex]) : string.Empty;
 87	        }
 88	
 89	        return string.Join(",", selectedFields);
 90	    }
 91	
 92	    private static string EscapeCsvField(string value)
 93	    {
 94	        if (value.Length == 0)
 95	        {
 96	            return string.Empty;
 97	        }
 98	
 99	        var requiresQuoting = value.Contains(',') ||
100	            value.Contains('"') ||
101	            value.Contains('\r') ||
102	            value.Contains('\n');
103	
104	        if (!requiresQuoting)
105	        {
106	            return value;
107	        }
108	
109	        var escaped = value.Replace("\"", "\"\"");
110	        return $"\"{escaped}\"";
111	    }
